Write a function that returns a custom hook bound to a specific store shape.

**Requirements:**
1. Import `useEffect`, `useState` from `react`.
2. Define and export a generic factory:
   ```ts
   createResourceHook<T>(loader: () => Promise<T>): () => {
     data: T | null;
     loading: boolean;
     error: Error | null;
   };
   ```
3. The factory returns a hook that:
   - tracks `data`, `loading`, and `error` state
   - on mount, sets `loading = true`, calls `loader()`, then populates `data` / `error`
   - cleans up by tracking a `cancelled` flag so stale promise resolutions don't update unmounted components.

Consumers get a purpose-built hook: `const useUser = createResourceHook(fetchUser); const { data } = useUser();`.

files.content:
import { useEffect, useState } from 'react';

export function createResourceHook<T>(loader: () => Promise<T>) {
  return function useResource() {
    const [data, setData] = useState<T | null>(null);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<Error | null>(null);

    useEffect(() => {
      let cancelled = false;
      setLoading(true);
      loader()
        .then((result) => {
          if (cancelled) return;
          setData(result);
          setLoading(false);
        })
        .catch((err: unknown) => {
          if (cancelled) return;
          setError(err instanceof Error ? err : new Error(String(err)));
          setLoading(false);
        });
      return () => {
        cancelled = true;
      };
    }, []);

    return { data, loading, error };
  };
}
